/* eslint-disable @stencil-community/required-jsdoc */
import { Component, h, Prop, Element, Host, Fragment, State, Watch } from '@stencil/core';
import { Status } from '@src/shared/base-props';
import { TimezoneInfo } from '@src/shared/timezone';
import { dayjsToNativeDate, LOCAL_TIMEZONE, utcOffsetToLabel, isYearFirst } from '../../utils';
import dayjs, { Dayjs } from 'dayjs';
import { cacheOrUpdate } from '@src/shared/perf/cache';
import { DateTimeFormatOptions, NormalizedDatePickerComparisonProps } from '../../types';
import { datePickerMessages } from '@fe-infra/keystone-locales';
import { t } from '@src/shared/i18n';
import { globalConfigStore } from '@src/shared/stores';
import { Slot, Slots } from '@src/framework/decorators';
import { KsIconCalendar, KsIconFilledClose } from '@fe-infra/keystone-icons-stencil';

const prefix = 'display-field';

@Component({
  tag: 'ks-date-time-picker-display-field',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsDateTimePickerDisplayField {
  @Element() el!: HTMLKsDateTimePickerDisplayFieldElement;
  /** The current values to display in the input field(s). */
  @Prop() value!: [Dayjs | null, Dayjs | null];
  /** If true, the presenter will display two input fields for a range. If false, a single input field is displayed. */
  @Prop() isRange = false;
  /** Placeholder text for the input field when `isRange` is false and no value is present. */
  @Prop() placeholder!: [string | undefined, string | undefined];
  /** If true, the input field(s) will be disabled and non-interactive. */
  @Prop() disabled!: [boolean, boolean];
  /** If true, enable the comparison mode. */
  @Prop() comparison!: NormalizedDatePickerComparisonProps;
  /** If true, a clear button is shown when the input has a value and is focused, allowing the user to clear the content. */
  @Prop() clearable!: boolean;
  /** Sets the validation status of the input, affecting its visual style (e.g., 'error', 'warning'). */
  @Prop() status!: Status;
  /** The timezone info */ // TODO label 应当允许完全自定义的节点
  @Prop() timezone!: TimezoneInfo;
  /** Whether or not to show the timezone indicator. */
  @Prop() showTimezone!: false | { placement: 'input' | 'panel'; style?: 'longOffset' | 'full' }; // TODO label 应当允许完全自定义的节点
  @Prop() open!: boolean;
  @Prop() forceActive!: boolean;
  @Prop() hoverPart!: 'start' | 'end' | null;

  @Prop() displayFormatOptions!: DateTimeFormatOptions;

  @Prop() handleClear!: () => void;

  @Slot({ slotname: 'prefix' }) private prefixSlot?: Slots;

  @State() isFocused = false;

  /** Use this to prevent frequent flashing of the hover effect */
  @State() debouncedHoverPart: 'start' | 'end' | null = null;
  private _clearResetHoverPartTimer: (() => void) | null = null;
  @Watch('hoverPart')
  handleHoverPartChange(hoverPart: 'start' | 'end' | null) {
    this._clearResetHoverPartTimer?.();

    if (hoverPart === this.debouncedHoverPart) {
      return;
    }

    if (hoverPart) {
      this.debouncedHoverPart = hoverPart;
    } else {
      const timer = setTimeout(() => {
        this.debouncedHoverPart = null;
      }, 200);
      this._clearResetHoverPartTimer = () => clearTimeout(timer);
    }
  }
  connectedCallback() {
    this.handleHoverPartChange(this.hoverPart);
  }

  get locale() {
    return globalConfigStore.state.locale;
  }

  private getDisplayValueFormatter = cacheOrUpdate(
    this.locale,
    () => {
      // Intl.DateTimeFormat does not support formatting quarters, so we filter it out and handle it manually later.
      const { quarter, ...restOptions } = this.displayFormatOptions || {};
      return new Intl.DateTimeFormat(this.locale, restOptions);
    },
    JSON.stringify(this.displayFormatOptions),
  );
  private formatToDisplayValue = (value: dayjs.Dayjs | null) => {
    if (!value) {
      return null;
    }
    if (typeof this.timezone.utcOffset === 'number') {
      // As we always use UTC for internal calculation when timezone is set to a fixed utcOffset,
      // we need to convert it to the local timezone for display
      value = value.tz(LOCAL_TIMEZONE, true);
    }
    const formattedDate = this.getDisplayValueFormatter(this.locale).format(dayjsToNativeDate(value));

    if (this.displayFormatOptions.quarter === 'short') {
      const quarterString = `Q${value.quarter()}`;

      if (isYearFirst(this.locale)) {
        return [formattedDate, quarterString].filter(Boolean).join(' ');
      } else {
        return [quarterString, formattedDate].filter(Boolean).join(' ');
      }
    }

    return formattedDate;
  };

  get startDisplayValue(): string | null {
    return this.value[0] && this.formatToDisplayValue(this.value[0]);
  }
  get endDisplayValue(): string | null {
    return this.value[1] && this.formatToDisplayValue(this.value[1]);
  }
  get startDisabled() {
    return Array.isArray(this.disabled) ? this.disabled[0] : this.disabled;
  }
  get endDisabled() {
    return Array.isArray(this.disabled) ? this.disabled[1] : this.disabled;
  }
  get startPlaceholder() {
    return this.placeholder[0] === undefined ? t(datePickerMessages.start) : this.placeholder[0];
  }
  get endPlaceholder() {
    return this.placeholder[1] === undefined ? t(datePickerMessages.end) : this.placeholder[1];
  }
  get showComparison(): boolean {
    return this.comparison.active && Boolean(this.comparison.value[0] || this.comparison.value[1]);
  }
  get startComparisonDisplayValue(): string | null {
    return this.formatToDisplayValue(this.comparison.value[0]);
  }
  get endComparisonDisplayValue(): string | null {
    return this.formatToDisplayValue(this.comparison.value[1]);
  }

  private handleFocusField = () => {
    this.isFocused = true;
  };
  private handleBlurField = () => {
    // TODO blur 事件应该通知外部
    this.isFocused = false;
  };
  private _handleClear = (event: MouseEvent) => {
    event.stopPropagation();
    this.handleClear();
  };
  private handleClick = (event: MouseEvent) => {
    if (this.disabled[0] && this.disabled[1]) {
      event.stopImmediatePropagation();
      event.stopPropagation();
    }
  };

  private renderDisplayValue() {
    return (
      <Fragment>
        <div
          class={{
            [`${prefix}__display-value`]: true,
            [`${prefix}__display-value--placeholder`]: !this.startDisplayValue,
            [`${prefix}__display-value--hover`]: this.open && this.isRange && this.debouncedHoverPart === 'start',
            [`${prefix}__display-value--disabled`]: this.startDisabled,
          }}
        >
          {this.startDisplayValue || this.startPlaceholder}
          {this.showComparison && (
            <div class={`${prefix}__comparison-display-value`}>{this.startComparisonDisplayValue}</div>
          )}
        </div>

        {this.isRange && (
          <Fragment>
            <div>
              <div class={`${prefix}__divider`} />
              {this.showComparison && <div class={`${prefix}__divider`} />}
            </div>

            <div
              class={{
                [`${prefix}__display-value`]: true,
                [`${prefix}__display-value--placeholder`]: !this.endDisplayValue,
                [`${prefix}__display-value--hover`]: this.open && this.debouncedHoverPart === 'end',
                [`${prefix}__display-value--disabled`]: this.endDisabled,
              }}
            >
              {this.endDisplayValue || this.endPlaceholder}
              {this.showComparison && (
                <div class={`${prefix}__comparison-display-value`}>{this.endComparisonDisplayValue}</div>
              )}
            </div>
          </Fragment>
        )}
      </Fragment>
    );
  }
  private renderUtcOffsetLabel() {
    if (typeof this.timezone.utcOffset !== 'number') {
      return;
    }

    if (this.showTimezone && this.showTimezone.placement === 'input') {
      const utcOffsetLabel = utcOffsetToLabel(this.timezone.utcOffset);
      const timezoneLabelContainer = (
        <div
          class={{
            [`${prefix}__timezone`]: true,
            [`${prefix}__timezone--with-help`]: Boolean(this.timezone.helpContent),
          }}
          part="fieldTimezone"
        >
          {utcOffsetLabel}
        </div>
      );
      return this.timezone.helpContent ? (
        <ks-tooltip size="md" placement="bottom">
          {timezoneLabelContainer}
          <ks-text variant="labelSm" slot="content" richTextString={this.timezone.helpContent} />
        </ks-tooltip>
      ) : (
        timezoneLabelContainer
      );
    }
  }
  private renderSuffixIcon() {
    const showClearButton =
      this.clearable &&
      (this.isFocused || this.open) &&
      (this.startDisplayValue || this.endDisplayValue) &&
      !this.startDisabled &&
      !this.endDisabled;

    if (showClearButton) {
      return (
        <KsIconFilledClose
          part="suffix-icon"
          class={{
            [`${prefix}__suffix-icon`]: true,
            [`${prefix}__clear`]: true,
          }}
          onClick={this._handleClear}
          data-testid="base-pick-presenter-3KqV18"
        />
      );
    } else {
      return <KsIconCalendar class={`${prefix}__suffix-icon`} part="suffix-icon" />;
    }
  }
  render() {
    return (
      <Host onClick={this.handleClick} data-testid="display-field-index-iAoTmA">
        <button
          disabled={this.startDisabled && this.endDisabled}
          class={{
            [prefix]: true,
            [`${prefix}--${this.status}`]: true,
            [`${prefix}--disabled`]: this.startDisabled && this.endDisabled,
            [`${prefix}--force-active`]: this.forceActive,
            [`${prefix}--comparison`]: this.showComparison,
          }}
          onFocus={this.handleFocusField}
          onBlur={this.handleBlurField}
          data-testid="base-pick-presenter-jC6S8N"
        >
          {this.prefixSlot && <slot name="prefix"></slot>}

          {this.renderDisplayValue()}

          <div class={`${prefix}__suffix`} part="suffix">
            {this.renderUtcOffsetLabel()}
            <slot name="suffix"></slot>
            {this.renderSuffixIcon()}
          </div>
        </button>
      </Host>
    );
  }
}
